CREATE TABLE IF NOT EXISTS cms_forms(id INTEGER PRIMARY KEY AUTOINCREMENT,form_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','active','archived')),settings_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_form_fields(id INTEGER PRIMARY KEY AUTOINCREMENT,form_id INTEGER NOT NULL REFERENCES cms_forms(id) ON DELETE CASCADE,field_key TEXT NOT NULL,label TEXT NOT NULL,field_type TEXT NOT NULL,required INTEGER NOT NULL DEFAULT 0 CHECK(required IN(0,1)),position INTEGER NOT NULL DEFAULT 0,validation_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',UNIQUE(form_id,field_key));
CREATE TABLE IF NOT EXISTS cms_form_submissions(id INTEGER PRIMARY KEY AUTOINCREMENT,form_id INTEGER NOT NULL REFERENCES cms_forms(id) ON DELETE CASCADE,status TEXT NOT NULL DEFAULT 'new' CHECK(status IN('new','processing','completed','rejected')),payload_json TEXT NOT NULL,source_ip_hash TEXT NOT NULL DEFAULT '',user_agent_hash TEXT NOT NULL DEFAULT '',submitted_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_cms_form_submissions_form ON cms_form_submissions(form_id,status,created_at DESC);
CREATE TABLE IF NOT EXISTS cms_custom_field_definitions(id INTEGER PRIMARY KEY AUTOINCREMENT,field_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,entity_type TEXT NOT NULL,field_type TEXT NOT NULL,validation_json TEXT NOT NULL DEFAULT '{}',settings_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_custom_field_values(field_id INTEGER NOT NULL REFERENCES cms_custom_field_definitions(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,value_json TEXT NOT NULL DEFAULT 'null',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(field_id,entity_type,entity_id));
CREATE TABLE IF NOT EXISTS cms_workflows(id INTEGER PRIMARY KEY AUTOINCREMENT,workflow_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,entity_type TEXT NOT NULL,initial_state TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_workflow_transitions(id INTEGER PRIMARY KEY AUTOINCREMENT,workflow_id INTEGER NOT NULL REFERENCES cms_workflows(id) ON DELETE CASCADE,from_state TEXT NOT NULL,to_state TEXT NOT NULL,permission_key TEXT NOT NULL DEFAULT '',conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',UNIQUE(workflow_id,from_state,to_state));
CREATE TABLE IF NOT EXISTS cms_workflow_events(id INTEGER PRIMARY KEY AUTOINCREMENT,workflow_id INTEGER NOT NULL REFERENCES cms_workflows(id) ON DELETE CASCADE,entity_type TEXT NOT NULL,entity_id INTEGER NOT NULL,from_state TEXT,to_state TEXT NOT NULL,actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cms_automation_recipes(id INTEGER PRIMARY KEY AUTOINCREMENT,recipe_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,trigger_event TEXT NOT NULL,conditions_json TEXT NOT NULL DEFAULT '{}',actions_json TEXT NOT NULL DEFAULT '[]',is_enabled INTEGER NOT NULL DEFAULT 1 CHECK(is_enabled IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.18.0');